  "view_hash": "7c33bd48669b085655dcfdfdf8c16fcee8ddfd3cd77bf632c064797d50de3a9d",
  "fim_base": {
    "estado": "exato",
    "valor": 12,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declarada fixa o término em D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_113c08",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "As precedências estão referidas à ficha d_a70f, mas essa ficha e suas relações não estão disponíveis na view."
    ],
    "motivo": "As durações de duas atividades mudam, mas sem as precedências não é possível determinar como isso afeta a data do marco final.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_113c08",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Faltam as precedências necessárias para determinar a variação do término em relação a D12."
    ],
    "motivo": "A alteração das durações não basta para calcular a variação do marco final sem presumir relações entre atividades.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "A referência fixa declara R$ 1.650,00; as obrigações listadas totalizam esse valor.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_113c08",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493c",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O término novo é desconhecido, portanto não se pode determinar se há dias extras de apoio nem o respectivo valor."
    ],
    "motivo": "O aviso não cobra diretamente, mas o apoio pode variar com a extensão do projeto; o término novo não pode ser calculado sem as precedências.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_113c08",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493c",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Faltam as precedências para determinar o término e, consequentemente, se incide custo de extensão do apoio."
    ],
    "motivo": "Sem o efeito da alteração sobre o término, não é possível determinar o sinal nem a magnitude da variação do custo.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso substitui duas durações e não inclui cobrança direta. A view não contém as precedências necessárias para calcular o efeito no marco final; como o custo do apoio depende do término, também não é possível determinar o custo novo nem sua variação."
}

